parameters.name:
{
  report,
  isDark,
  setReport,
}

parameters.type:
{
  report: IndividualReport | null;
  isDark: boolean;
  setReport: (r: IndividualReport) => void;
}

calls.targetName:
timeframes
    .map((tf) => {
      const items = report.actionPlan.filter((a) => a.timeframe === tf);
      if (items.length === 0) return '';
      const itemRows = items
        .map(
          (item) =>
            `<tr>
              <td>${item.action}</td>
              <td>${item.impact}</td>
              <td class="num">${item.estimatedBenefit > 0 ? formatCurrency(item.estimatedBenefit) : '—'}</td>
            </tr>`,
        )
        .join('');
      return `<div class="action-group">
        <div class="action-tf-header">${tf}</div>
        <table class="data-table">
          <thead><tr><th>Action</th><th>Impact</th><th>Benefit</th></tr></thead>
          <tbody>${itemRows}</tbody>
        </table>
      </div>`;
    }).join
